"""Relative date arithmetic and natural language date expressions."""

from datetime import datetime, timedelta
from typing import Optional

from dateutil.relativedelta import relativedelta
from dateutil.rrule import rrule, WEEKLY, MO, TU, WE, TH, FR, SA, SU
from dateutil.parser import parse as parse_dateutil

WEEKDAY_MAP = {
    "monday": MO,
    "tuesday": TU,
    "wednesday": WE,
    "thursday": TH,
    "friday": FR,
    "saturday": SA,
    "sunday": SU,
}


class RelativeDate:
    """Compute relative dates based on natural language expressions.

    Supports expressions like:
    - "next month"
    - "first Monday of next month"
    - "last Friday of this year"
    - "2 weeks from now"
    - "3 months ago"
    """

    def __init__(self, base: Optional[datetime] = None):
        """Initialize with a base datetime.

        Args:
            base: The reference datetime. Defaults to now.
        """
        self.base = base or datetime.now()

    def set_base(self, base: datetime) -> "RelativeDate":
        """Set a new base datetime.

        Args:
            base: The new reference datetime.

        Returns:
            Self for method chaining.
        """
        self.base = base
        return self

    def add(self, **kwargs) -> datetime:
        """Add time to the base date.

        Args:
            **kwargs: Time units to add (years, months, weeks, days,
                hours, minutes, seconds).

        Returns:
            The new datetime after adding the time units.
        """
        return self.base + relativedelta(**kwargs)

    def subtract(self, **kwargs) -> datetime:
        """Subtract time from the base date.

        Args:
            **kwargs: Time units to subtract (years, months, weeks, days,
                hours, minutes, seconds).

        Returns:
            The new datetime after subtracting the time units.
        """
        return self.base - relativedelta(**kwargs)

    def next(self, unit: str, weekday: Optional[str] = None) -> datetime:
        """Get the next occurrence of a time unit or weekday.

        Args:
            unit: The unit to advance ("month", "year", "week", "day").
            weekday: Optional day name for finding the next occurrence
                of a specific weekday.

        Returns:
            The next occurrence of the specified unit or weekday.
        """
        if weekday:
            wd = WEEKDAY_MAP[weekday.lower()]
            return self.base + relativedelta(weekday=wd)

        unit_map = {
            "day": {"days": 1},
            "week": {"weeks": 1},
            "month": {"months": 1},
            "year": {"years": 1},
        }

        if unit not in unit_map:
            raise ValueError(f"Unknown unit: {unit}")

        return self.base + relativedelta(**unit_map[unit])

    def last(self, unit: str, weekday: Optional[str] = None) -> datetime:
        """Get the last occurrence of a time unit or weekday.

        Args:
            unit: The unit to go back ("month", "year", "week", "day").
            weekday: Optional day name for finding the last occurrence
                of a specific weekday.

        Returns:
            The last occurrence of the specified unit or weekday.
        """
        if weekday:
            wd = WEEKDAY_MAP[weekday.lower()]
            return self.base + relativedelta(weekday=wd, weeks=-1)

        unit_map = {
            "day": {"days": -1},
            "week": {"weeks": -1},
            "month": {"months": -1},
            "year": {"years": -1},
        }

        if unit not in unit_map:
            raise ValueError(f"Unknown unit: {unit}")

        return self.base + relativedelta(**unit_map[unit])

    def nth_weekday_of_month(
        self,
        n: int,
        weekday_name: str,
        month: Optional[int] = None,
        year: Optional[int] = None,
    ) -> datetime:
        """Get the nth weekday of a specific month.

        Args:
            n: Which occurrence (1 for first, 2 for second, etc.).
            weekday_name: Name of the weekday ("monday", "tuesday", etc.).
            month: The month (1-12). Defaults to current month.
            year: The year. Defaults to current year.

        Returns:
            The datetime of the nth weekday of the month.
        """
        wd = WEEKDAY_MAP[weekday_name.lower()]
        target_year = year or self.base.year
        target_month = month or self.base.month

        first_day = datetime(target_year, target_month, 1)
        weekdays_in_month = list(
            rrule(
                WEEKLY,
                dtstart=first_day,
                byweekday=wd,
                count=5,
                cache=True,
            )
        )

        if n < 1 or n > len(weekdays_in_month):
            raise ValueError(
                f"No {n}th {weekday_name} in {target_month}/{target_year}"
            )

        return weekdays_in_month[n - 1]

    def parse_expression(self, expression: str) -> datetime:
        """Parse a natural language date expression.

        Handles expressions like:
        - "next Monday"
        - "the first Monday of next month"
        - "3 months from now"
        - "last Friday of December"

        Args:
            expression: The natural language date expression.

        Returns:
            The computed datetime.
        """
        expr = expression.strip().lower()

        if "next" in expr and "weekday" in WEEKDAY_MAP:
            for wd_name in WEEKDAY_MAP:
                if wd_name in expr:
                    return self.next(weekday=wd_name)

        if "first" in expr and "weekday" in WEEKDAY_MAP:
            for wd_name in WEEKDAY_MAP:
                if wd_name in expr and "first" in expr:
                    month_match = "next month" in expr or "of next month" in expr
                    month = None
                    year = None
                    if month_match:
                        next_month = self.base.month + 1
                        if next_month > 12:
                            next_month = 1
                            year = self.base.year + 1
                        else:
                            year = self.base.year
                        month = next_month
                    return self.nth_weekday_of_month(1, wd_name, month, year)

        if "last" in expr and "weekday" in WEEKDAY_MAP:
            for wd_name in WEEKDAY_MAP:
                if wd_name in expr and "last" in expr:
                    return self.last(weekday=wd_name)

        if "from now" in expr:
            return self._parse_relative_future(expr)

        if "ago" in expr:
            return self._parse_relative_past(expr)

        if "next month" in expr:
            return self.next("month")

        if "last month" in expr:
            return self.last("month")

        return self.base

    def _parse_relative_future(self, expr: str) -> datetime:
        """Parse expressions like '3 weeks from now'."""
        parts = expr.replace("from now", "").strip()
        return self._parse_relative(expr, future=True)

    def _parse_relative_past(self, expr: str) -> datetime:
        """Parse expressions like '3 months ago'."""
        parts = expr.replace("ago", "").strip()
        return self._parse_relative(expr, future=False)

    def _parse_relative(self, expr: str, future: bool = True) -> datetime:
        """Parse expressions with time units like '3 weeks from now' or '2 months ago'."""
        parts = expr.replace("from now", "").replace("ago", "").strip()

        unit_map = {
            "year": "years",
            "month": "months",
            "week": "weeks",
            "day": "days",
            "hour": "hours",
            "minute": "minutes",
            "second": "seconds",
        }

        for word, unit in unit_map.items():
            if word in parts:
                parts = parts.replace(word, unit)

        try:
            amount_str = parts.split()[0]
            amount = int(amount_str)
            if not future:
                amount = -amount
            return self.base + relativedelta(**{unit: amount})
        except (ValueError, IndexError):
            return self.base

    def diff(self, other: datetime, unit: str = "days") -> float:
        """Calculate the difference between the base date and another date.

        Args:
            other: The target datetime.
            unit: The unit for the difference
                ("years", "months", "weeks", "days", "hours", "minutes", "seconds").

        Returns:
            The difference in the specified unit.
        """
        delta = other - self.base
        if unit == "years":
            return delta.total_seconds() / (365.25 * 24 * 3600)
        if unit == "months":
            return delta.days / 30.44
        if unit == "weeks":
            return delta.days / 7
        if unit == "days":
            return delta.days
        if unit == "hours":
            return delta.total_seconds() / 3600
        if unit == "minutes":
            return delta.total_seconds() / 60
        if unit == "seconds":
            return delta.total_seconds()
        raise ValueError(f"Unknown unit: {unit}")


def relative_date(expression: str, base: Optional[datetime] = None) -> datetime:
    """Compute a relative date from a natural language expression.

    Args:
        expression: The natural language date expression.
        base: Optional base datetime. Defaults to now.

    Returns:
        The computed datetime.
    """
    rd = RelativeDate(base)
    return rd.parse_expression(expression)

"""Command-line interface for flexidate."""

import argparse
import sys
from datetime import datetime

from flexidate.parser import parse_date, parse_date_range, parse_multiple_dates
from flexidate.relative import relative_date, RelativeDate


def cmd_parse(args):
    """Handle the 'parse' subcommand."""
    try:
        if args.dates:
            dates = parse_multiple_dates(args.dates)
            for d in dates:
                print(d.isoformat())
        elif args.start and args.end:
            start, end = parse_date_range(args.start, args.end)
            print(f"{start.isoformat()} to {end.isoformat()}")
        else:
            date_str = args.date
            if date_str:
                result = parse_date(date_str)
                print(result.isoformat())
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def cmd_relative(args):
    """Handle the 'relative' subcommand."""
    base = None
    if args.base:
        try:
            base = parse_date(args.base)
        except ValueError as e:
            print(f"Error parsing base date: {e}", file=sys.stderr)
            sys.exit(1)

    try:
        result = relative_date(args.expression, base)
        print(result.isoformat())
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def cmd_diff(args):
    """Handle the 'diff' subcommand."""
    base = datetime.now()
    if args.base:
        try:
            base = parse_date(args.base)
        except ValueError as e:
            print(f"Error parsing base date: {e}", file=sys.stderr)
            sys.exit(1)

    target = parse_date(args.date)
    rd = RelativeDate(base)
    diff_value = rd.diff(target, args.unit)

    if args.unit in ("years", "months"):
        print(f"{diff_value:.2f} {args.unit}")
    else:
        print(f"{diff_value:.0f} {args.unit}")


def main():
    """Main entry point for the CLI."""
    parser = argparse.ArgumentParser(
        prog="flexidate",
        description="Parse dates and compute relative date arithmetic",
    )
    subparsers = parser.add_subparsers(dest="command")

    parse_parser = subparsers.add_parser("parse", help="Parse date string(s)")
    parse_parser.add_argument("date", nargs="?", help="Date string to parse")
    parse_parser.add_argument("dates", nargs="+", help="Multiple date strings")
    parse_parser.add_argument("--start", help="Start date")
    parse_parser.add_argument("--end", help="End date")

    relative_parser = subparsers.add_parser(
        "relative", help="Compute relative date from expression"
    )
    relative_parser.add_argument("expression", help="Relative date expression")
    relative_parser.add_argument(
        "--base", help="Base datetime (defaults to now)"
    )

    diff_parser = subparsers.add_parser("diff", help="Calculate date difference")
    diff_parser.add_argument("date", help="Target date")
    diff_parser.add_argument(
        "--base", help="Base datetime (defaults to now)"
    )
    diff_parser.add_argument(
        "--unit",
        default="days",
        choices=["years", "months", "weeks", "days", "hours", "minutes", "seconds"],
        help="Unit for the difference",
    )

    args = parser.parse_args()

    if args.command == "parse":
        cmd_parse(args)
    elif args.command == "relative":
        cmd_relative(args)
    elif args.command == "diff":
        cmd_diff(args)
    else:
        parser.print_help()


if __name__ == "__main__":
    main()

